//! Native XGK EtherNet/IP / OPC UA export tags.
use crate::{XgwxDocument, XgwxError, internal::decode_base64_payload};

/// One exported scalar PLC tag; OPC UA node IDs are generated by the server.
#[derive(Debug, Clone, PartialEq, Eq)]
#[cfg_attr(feature = "wasm", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "wasm", serde(rename_all = "camelCase", deny_unknown_fields))]
pub struct OpcUaTag {
    /// Unique exported tag name.
    pub name: String,
    /// Native bit-string or explicitly signed/unsigned scalar integer type.
    pub data_type: String,
    /// Native PLC device area.
    pub address_area: String,
    /// Native bit offset for P/M/K/L, or word offset for D.
    pub address_number: u32,
    /// User-facing description.
    pub comment: String,
}

struct Record {
    tag: OpcUaTag,
    #[cfg(feature = "write")]
    raw: Vec<u8>,
}
fn fail(reason: &str) -> XgwxError {
    XgwxError::BrowserNetworkEdit(reason.into())
}
fn string(bytes: &[u8], offset: &mut usize) -> Result<String, XgwxError> {
    let header = bytes
        .get(*offset..*offset + 4)
        .ok_or_else(|| fail("truncated OPC UA tag string"))?;
    if header[..3] != [255, 254, 255] || header[3] == 255 {
        return Err(fail("unsupported OPC UA tag string layout"));
    }
    let len = usize::from(header[3]) * 2;
    *offset += 4;
    let value = bytes
        .get(*offset..*offset + len)
        .ok_or_else(|| fail("truncated OPC UA tag string"))?;
    *offset += len;
    String::from_utf16(
        &value
            .chunks_exact(2)
            .map(|p| u16::from_le_bytes([p[0], p[1]]))
            .collect::<Vec<_>>(),
    )
    .map_err(|_| fail("invalid OPC UA tag UTF-16"))
}
fn number(bytes: &[u8], offset: &mut usize) -> Result<u32, XgwxError> {
    let value = bytes
        .get(*offset..*offset + 4)
        .ok_or_else(|| fail("truncated OPC UA tag number"))?;
    *offset += 4;
    Ok(u32::from_le_bytes(value.try_into().unwrap()))
}
fn records(doc: &XgwxDocument, configuration: usize) -> Result<Vec<Record>, XgwxError> {
    let configs: Vec<_> = doc.root.descendants_named("Configuration").collect();
    let config = configs
        .get(configuration)
        .ok_or_else(|| fail("OPC UA tag configuration is absent"))?;
    let tables: Vec<_> = config.descendants_named("EIPTags").collect();
    let [table] = tables.as_slice() else {
        return Err(fail("OPC UA tag table is absent or ambiguous"));
    };
    if !table.children.is_empty() {
        return Err(fail("XML-form OPC UA tags are not yet supported"));
    }
    let count: usize = table
        .attribute("Count")
        .and_then(|v| v.parse().ok())
        .ok_or_else(|| fail("invalid OPC UA tag count"))?;
    let compressed = table
        .attribute("Compressed")
        .is_some_and(|v| matches!(v, "1" | "true"));
    let bytes = decode_base64_payload(&table.text, compressed)?.data;
    let mut offset = 0;
    let mut result = Vec::new();
    // Each scalar record needs at least seven native string headers and two u32s.
    if count > bytes.len() / 36 {
        return Err(fail("OPC UA tag count exceeds the payload"));
    }
    for _ in 0..count {
        #[cfg(feature = "write")]
        let start = offset;
        if string(&bytes, &mut offset)? != "SV5.0" {
            return Err(fail("unsupported OPC UA tag version"));
        }
        let name = string(&bytes, &mut offset)?;
        let address_area = string(&bytes, &mut offset)?;
        let address_number = number(&bytes, &mut offset)?;
        let data_type = string(&bytes, &mut offset)?;
        let comment = string(&bytes, &mut offset)?;
        let _source_ref = string(&bytes, &mut offset)?;
        let _flags = number(&bytes, &mut offset)?;
        let _range = string(&bytes, &mut offset)?;
        result.push(Record {
            tag: OpcUaTag {
                name,
                data_type,
                address_area,
                address_number,
                comment,
            },
            #[cfg(feature = "write")]
            raw: bytes[start..offset].to_vec(),
        });
    }
    if offset != bytes.len() {
        return Err(fail("unsupported trailing OPC UA tag data"));
    }
    Ok(result)
}

impl crate::NetworkView<'_> {
    /// Decode one configuration's native XGK export tags in their file order.
    /// Unsupported formats fail explicitly instead of showing an empty list.
    pub fn opcua_tags(&self, configuration_index: usize) -> Result<Vec<OpcUaTag>, XgwxError> {
        Ok(records(self.doc, configuration_index)?
            .into_iter()
            .map(|r| r.tag)
            .collect())
    }
}

#[cfg(feature = "write")]
mod write {
    use super::*;
    /// One create, update, or delete operation guarded by the complete old tag list.
    #[derive(Debug, Clone)]
    #[cfg_attr(feature = "wasm", derive(serde::Deserialize))]
    #[cfg_attr(feature = "wasm", serde(rename_all = "camelCase", deny_unknown_fields))]
    pub struct OpcUaTagPatch {
        /// Configuration index in document order.
        pub configuration_index: usize,
        /// Entire previously inspected tag list, guarding reordering and additions.
        pub expected_tags: Vec<OpcUaTag>,
        /// Existing tag index; None appends a new tag.
        pub index: Option<usize>,
        /// Replacement or new tag; None deletes the selected existing tag.
        pub tag: Option<OpcUaTag>,
    }
    fn put(out: &mut Vec<u8>, value: &str) {
        out.extend_from_slice(&[255, 254, 255, value.encode_utf16().count() as u8]);
        for unit in value.encode_utf16() {
            out.extend_from_slice(&unit.to_le_bytes());
        }
    }
    fn encode(tag: &OpcUaTag) -> Result<Vec<u8>, XgwxError> {
        if tag.name.is_empty()
            || tag.name.encode_utf16().count() > 32
            || !tag
                .name
                .chars()
                .next()
                .is_some_and(|c| c.is_alphabetic() || c == '_')
            || !tag.name.chars().all(|c| c.is_alphanumeric() || c == '_')
        {
            return Err(fail(
                "tag name must start with a letter or underscore and contain at most 32 letters, digits or underscores",
            ));
        }
        if !matches!(
            tag.data_type.as_str(),
            "BIT"
                | "BYTE"
                | "SINT"
                | "USINT"
                | "WORD"
                | "INT"
                | "UINT"
                | "DWORD"
                | "DINT"
                | "UDINT"
                | "LWORD"
                | "LINT"
                | "ULINT"
        ) {
            return Err(fail("unsupported scalar OPC UA tag type"));
        }
        // These direct areas avoid special-module, banked and index-register encodings.
        if !matches!(tag.address_area.as_str(), "P" | "M" | "K" | "L" | "D")
            || tag.address_number > 32767
        {
            return Err(fail(
                "supported tag addresses use P, M, K, L or D with a native offset from 0 to 32767",
            ));
        }
        if matches!(tag.data_type.as_str(), "BIT" | "BYTE" | "SINT" | "USINT")
            && tag.address_area == "D"
        {
            return Err(fail(
                "BIT and 8-bit nodes require a bit-addressed P, M, K or L device",
            ));
        }
        let width = match tag.data_type.as_str() {
            "BIT" => 1,
            "BYTE" | "SINT" | "USINT" => 8,
            "WORD" | "INT" | "UINT" => 16,
            "DWORD" | "DINT" | "UDINT" => 32,
            "LWORD" | "LINT" | "ULINT" => 64,
            _ => unreachable!(),
        };
        if tag.address_area != "D" {
            let alignment = width.min(16);
            if !tag.address_number.is_multiple_of(alignment) || tag.address_number + width > 32768 {
                return Err(fail(
                    "device address is misaligned or extends beyond the supported area",
                ));
            }
        } else if tag.address_number + width / 16 > 32768 {
            return Err(fail("node extends beyond the supported D area"));
        }
        if tag.comment.encode_utf16().count() > 254 || tag.comment.chars().any(|c| c == '\0') {
            return Err(fail(
                "tag description must fit 254 UTF-16 units without NUL",
            ));
        }
        let mut out = Vec::new();
        for value in ["SV5.0", &tag.name, &tag.address_area] {
            put(&mut out, value);
        }
        out.extend_from_slice(&tag.address_number.to_le_bytes());
        for value in [&tag.data_type, &tag.comment, ""] {
            put(&mut out, value);
        }
        out.extend_from_slice(&1u32.to_le_bytes());
        put(&mut out, "[0:0]");
        Ok(out)
    }
    impl XgwxDocument {
        pub(crate) fn edit_opcua_tag(&mut self, patch: &OpcUaTagPatch) -> Result<(), XgwxError> {
            self.ensure_consistent_api_tree()?;
            let mut existing = records(self, patch.configuration_index)?;
            if existing
                .iter()
                .map(|r| &r.tag)
                .ne(patch.expected_tags.iter())
            {
                return Err(fail("stale OPC UA tag list; reload the editor"));
            }
            let xml = roxmltree::Document::parse(&self.xml).map_err(XgwxError::Xml)?;
            let config = xml
                .descendants()
                .filter(|n| n.has_tag_name("Configuration"))
                .nth(patch.configuration_index)
                .ok_or_else(|| fail("configuration is absent"))?;
            let cpu = config.attribute("Type").and_then(|s| s.parse::<u32>().ok());
            if !crate::cpu_catalog()
                .iter()
                .any(|c| c.family == "XGK" && Some(c.type_code) == cpu)
            {
                return Err(fail(
                    "OPC UA tag-list editing requires an XGK CPU; IEC CPUs use variable export flags",
                ));
            }
            match (patch.index, &patch.tag) {
                (Some(index), tag) => {
                    let old = existing
                        .get(index)
                        .ok_or_else(|| fail("OPC UA tag index is absent"))?;
                    // Rebuilding complex/opaque entries would lose hidden native metadata.
                    if tag.is_some() && old.raw != encode(&old.tag)? {
                        return Err(fail(
                            "this tag has additional native metadata and cannot be rebuilt",
                        ));
                    }
                    if let Some(tag) = tag {
                        existing[index] = Record {
                            tag: tag.clone(),
                            raw: encode(tag)?,
                        };
                    } else {
                        existing.remove(index);
                    }
                }
                (None, Some(tag)) => existing.push(Record {
                    tag: tag.clone(),
                    raw: encode(tag)?,
                }),
                _ => return Err(fail("a new OPC UA tag is required")),
            }
            if existing.len() > 1000 {
                return Err(fail("this writer supports up to 1000 scalar exported tags"));
            }
            let mut names = std::collections::HashSet::new();
            for record in &existing {
                if !names.insert(record.tag.name.to_lowercase()) {
                    return Err(fail("OPC UA tag names must be unique"));
                }
            }
            let table = config
                .descendants()
                .find(|n| n.has_tag_name("EIPTags"))
                .unwrap();
            let count = table
                .attribute_node("Count")
                .ok_or_else(|| fail("missing OPC UA tag count"))?;
            let raw = &self.xml[table.range()];
            let open_end = raw
                .find('>')
                .ok_or_else(|| fail("invalid OPC UA tag table"))?;
            let mut opening = raw[..open_end].trim_end_matches('/').to_owned();
            let relative = |range: std::ops::Range<usize>| {
                range.start - table.range().start..range.end - table.range().start
            };
            let mut header_edits =
                vec![(relative(count.range_value()), existing.len().to_string())];
            if let Some(compressed) = table.attribute_node("Compressed") {
                header_edits.push((relative(compressed.range_value()), "1".into()));
            } else {
                opening.push_str(" Compressed=\"1\"");
            }
            header_edits.sort_by_key(|(r, _)| std::cmp::Reverse(r.start));
            for (range, value) in header_edits {
                opening.replace_range(range, &value);
            }
            if table
                .attribute(("urn:schemas-microsoft-com:datatypes", "dt"))
                .is_none()
            {
                if table.lookup_namespace_uri(Some("dt")).is_none() {
                    opening.push_str(" xmlns:dt=\"urn:schemas-microsoft-com:datatypes\"");
                }
                opening.push_str(" dt:dt=\"bin.base64\"");
            }
            let payload = existing
                .iter()
                .flat_map(|r| r.raw.iter().copied())
                .collect::<Vec<_>>();
            let text = table.text().unwrap_or_default();
            let encoded = crate::writer::encode_payload_text(text, true, &payload)?;
            let replacement = format!("{opening}>{encoded}</EIPTags>");
            let mut candidate = self.clone();
            candidate.apply_xml_replacements(vec![(table.range(), replacement)])?;
            // Validate that native decode recovers exactly the requested table.
            if candidate.network().opcua_tags(patch.configuration_index)?
                != existing.iter().map(|r| r.tag.clone()).collect::<Vec<_>>()
            {
                return Err(fail("OPC UA tag verification failed"));
            }
            candidate.to_verified_bytes()?;
            *self = candidate;
            Ok(())
        }
    }
}
#[cfg(feature = "write")]
pub use write::OpcUaTagPatch;
